const {createRequire}=require('node:module');
const fs=require('node:fs');
const req=createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const {chromium}=req('playwright');
const config=JSON.parse(fs.readFileSync('/home/runner/.local/share/omgithub-playwright/linux.json','utf8'));
process.env.DISPLAY ||= ':'+fs.readFileSync('/home/runner/.local/share/omgithub-playwright/display','utf8').trim();
(async()=>{
 const browser=await chromium.launch(config.browser.launchOptions);
 const page=await browser.newPage({viewport:{width:1280,height:800}});
 page.on('pageerror',e=>{throw e});
 await page.goto('http://127.0.0.1:3000',{waitUntil:'load'});
 await page.locator('[data-group="gender"][data-value="1"]').click();
 if(await page.evaluate('state.gender')!==1) throw Error('Female character selection failed');
 if(!(await page.locator('[data-group="accessory"]').allTextContents()).includes('Lace parasol')) throw Error('Gender-specific accessories missing');
 await page.locator('#play').click();
 await page.waitForTimeout(300);
 const pad=page.locator('[data-dir="right"]');
 const box=await pad.boundingBox();
 const before=await page.evaluate('state.x');
 await page.mouse.move(box.x+box.width/2,box.y+box.height/2);
 await page.mouse.down();
 await page.waitForTimeout(350);
 await page.mouse.up();
 const after=await page.evaluate('state.x');
 if(after<=before) throw Error(`D-pad did not move right (${before} -> ${after})`);
 const rows=await page.locator('#touchPad').evaluate(el=>getComputedStyle(el).gridTemplateRows);
 await page.screenshot({path:'/tmp/opencode/latest.jpg',type:'jpeg',quality:82});
 console.log(JSON.stringify({gender:await page.evaluate('state.gender'),accessories:await page.locator('[data-group="accessory"]').allTextContents(),movedFrom:before,movedTo:after,dpadRows:rows,screen:'1280x800'}));
 await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
